council/past/2/proposals/mozzie-log.mjs:
// Mozzie, council 2. node proposals/mozzie-log.mjs [days=1]
// Question: Bath+Keyholder log every reading (1 s) so replay can reproduce decisions.
// How big is a day of that log, and how long does replaying it from t=0 take?
// Plant: Modulo's assumed bath; bang-bang +/-0.3 K; one log line per reading and per decision.
import { Sim } from '../tools/des/des.mjs';
const days = +(process.argv[2] || 1), END = days * 86400;
const C = 5 * 4186, P = 1000, UA = 8, AMB = 20, SET = 60, H = 0.3;
function record() {                     // the "live" run: plant injects, controller decides, all logged
  const sim = new Sim({ seed: 1 }), log = []; let T = 20, heat = 0;
  sim.process(function* plant() { for (;;) { T += (P * heat - UA * (T - AMB)) / C;
    const r = Math.round((T + 0.17 * (sim.random() - 0.5)) * 16) / 16; log.push({ t: sim.now, k: 'temp', v: r });
    sim.inject('temp', r); yield sim.timeout(1); } });
  sim.process(function* ctl() { for (;;) { const r = yield sim.signal('temp'); const w = r < SET - H ? 1 : r > SET + H ? 0 : heat;
    if (w !== heat) { heat = w; log.push({ t: sim.now, k: 'dec', v: w }); } } });
  sim.run({ until: END }); return log;
}
function replay(log) {                  // feed logged readings back, compare decisions one for one
  const sim = new Sim({ seed: 1 }), out = []; let heat = 0;
  const temps = log.filter(e => e.k === 'temp');
  sim.process(function* feed() { for (const e of temps) { if (e.t > sim.now) yield sim.timeout(e.t - sim.now); sim.inject('temp', e.v); yield sim.timeout(0); } });
  sim.process(function* ctl() { for (;;) { const r = yield sim.signal('temp'); const w = r < SET - H ? 1 : r > SET + H ? 0 : heat;
    if (w !== heat) { heat = w; out.push({ t: sim.now, k: 'dec', v: w }); } } });
  sim.run({ until: END + 1 }); return out;
}
let t0 = performance.now(); const log = record(); const tRec = performance.now() - t0;
const bytes = log.reduce((s, e) => s + JSON.stringify(e).length + 1, 0);
const decs = log.filter(e => e.k === 'dec');
t0 = performance.now(); const rep = replay(log); const tRep = performance.now() - t0;
const same = rep.length === decs.length && rep.every((e, i) => e.t === decs[i].t && e.v === decs[i].v);
console.log(JSON.stringify({ days, entries: log.length, decisions: decs.length, MB: +(bytes / 1e6).toFixed(2),
  MB_per_year: +(bytes / 1e6 / days * 365).toFixed(0), record_ms: Math.round(tRec), replay_ms: Math.round(tRep),
  replay_s_per_year_est: +(tRep / days * 365 / 1000).toFixed(0), replay_identical: same }));

council/past/3/proposals/modulo-debounce:
// Modulo: does tape's CardWatcher debounce hold a card on the pad? Measured, not argued.
// node proposals/modulo-debounce.mjs        (runs in a few seconds)
// A card sits on the pad for 1 h. The reader is polled at 8 Hz, and each poll misses with
// some probability. We count false "gone" events. Each one means: pause, save, WiFi up,
// card re-read, WiFi down, resume. A "bedtime" card without resume would restart the book.
import { Sim } from '../tools/des/des.mjs';

function run({ N, channel, seed, hours = 1 }) {
  const sim = new Sim({ seed });
  let falseGone = 0, believed = true, misses = 0, bad = false;
  // Gilbert-Elliott channel: a 'good' state misses with pg; a 'bad' state (a child leaning,
  // the card skewed in the nest) misses with pb.
  function* reader() {
    for (;;) {
      yield sim.timeout(0.125);
      if (channel.kind === 'iid') { sim.inject('read', sim.random() >= channel.p); continue; }
      if (sim.random() < (bad ? channel.leave : channel.enter)) bad = !bad;
      sim.inject('read', sim.random() >= (bad ? channel.pb : channel.pg));
    }
  }
  function* watcher() {           // the rule as written in tape/sim: N consecutive misses = gone
    for (;;) {
      const ok = yield sim.signal('read');
      if (ok) { misses = 0; believed = true; }
      else if (believed && ++misses >= N) { falseGone++; believed = false; misses = 0; }
    }
  }
  sim.process(watcher); sim.process(reader);
  sim.run({ until: hours * 3600 });
  return falseGone;
}

const channels = [
  { name: 'iid 5%', kind: 'iid', p: 0.05 },
  { name: 'iid 10%', kind: 'iid', p: 0.10 },
  { name: 'iid 25% (sim flaky)', kind: 'iid', p: 0.25 },
  // bursts: a 2 s bad spell about once a minute, 70% misses inside it, 2% outside
  { name: 'bursty 2s@70%/min', kind: 'ge', pg: 0.02, pb: 0.70, enter: 0.125 / 60, leave: 0.125 / 2 },
];
console.log('false "gone" per hour with the card never moved (mean of seeds 1-5)');
console.log('N  latency  ' + channels.map(c => c.name.padEnd(22)).join(''));
for (const N of [2, 3, 4, 6, 8, 12]) {
  const cells = channels.map(c => {
    let s = 0; for (let seed = 1; seed <= 5; seed++) s += run({ N, channel: c, seed });
    return (s / 5).toFixed(1).padEnd(22);
  });
  console.log(`${String(N).padEnd(3)}${(N * 0.125).toFixed(2).padStart(5)} s  ${cells.join('')}`);
}
// Cross-check for iid: runs of at least N misses start at rate 8 (1-p) p^N per second.
for (const p of [0.10, 0.25]) console.log(`closed form, iid ${p * 100}%, N=3: ${(8 * 3600 * (1 - p) * p ** 3).toFixed(1)}/h`);

council/past/3/proposals/modulo-torn.mjs:
// modulo-torn.mjs — Modulo, council 3 round 2.
// Same box as morphyx-absence.mjs (copied; it doesn't export), three SD events, four boot rules.
//   as-written     : file that doesn't parse  => {}
//   present        : Morphyx r1 — restore from mirror only if file absent
//   parses         : Mozzie r1 / CHOICE — restore if absent or unparseable
//   parses+gen     : also restore if the file parses but carries an older generation than the mirror
// Events: absent (file gone), torn (truncated by a desktop OS), stale (an older cards.json,
// half the bindings, dragged back from a laptop copy).
//   node proposals/modulo-torn.mjs
import { Sim } from '../tools/des/des.mjs';
const AUDIO = '/tape/audio/', CARDS = '/tape/cards.json';
function makeSD(files) {
  const sd = { files: new Map(Object.entries(files)) };
  sd.folders = () => [...new Set([...sd.files.keys()].filter((p) => p.startsWith(AUDIO))
    .map((p) => p.slice(AUDIO.length).split('/')[0]))].sort();
  return sd;
}
const parse = (s) => { try { const o = JSON.parse(s); return o && typeof o === 'object' ? o : null; } catch { return null; } };
function makeBox(sd, rule, nvs) {
  const box = { cards: {}, gen: 0 };
  box.boot = () => {
    const has = sd.files.has(CARDS), cur = has ? parse(sd.files.get(CARDS)) : null;
    const restore = () => { box.cards = { ...nvs.cards }; box.gen = nvs.gen; box.restored = true; };
    if (cur && rule === 'parses+gen' && nvs.cards && cur._gen !== undefined && cur._gen < nvs.gen) return restore();
    // a file with no _gen was written by a person, not the box: it decides
    if (cur) { const { _gen, ...c } = cur; box.cards = c; box.gen = _gen ?? 0; return; }
    if (nvs.cards && ((rule === 'present' && !has) || rule === 'parses' || rule === 'parses+gen')) return restore();
    box.cards = {};
  };
  box.place = (card) => {
    if (box.cards[card]) return box.cards[card];
    const free = sd.folders().filter((f) => !Object.values(box.cards).includes(f));
    if (!free.length) return null;
    box.cards[card] = free[0]; box.gen++;
    sd.files.set(CARDS, JSON.stringify({ ...box.cards, _gen: box.gen }));
    nvs.cards = { ...box.cards }; nvs.gen = box.gen;
    return free[0];
  };
  return box;
}
function trial(rule, ev, sim, B) {
  const files = {}; for (let i = 0; i < B; i++) files[`${AUDIO}book-${String(i).padStart(2, '0')}/001.m4a`] = 'x';
  const sd = makeSD(files), nvs = {};
  let box = makeBox(sd, rule, nvs); box.boot();
  let old = null;
  for (let i = 0; i < B; i++) { box.place(`C${i}`); if (i === Math.floor(B / 2) - 1) old = sd.files.get(CARDS); }
  const before = { ...box.cards };
  if (ev === 'absent') sd.files.delete(CARDS);
  if (ev === 'torn') { const s = sd.files.get(CARDS); sd.files.set(CARDS, s.slice(0, Math.floor(sim.uniform(0, s.length)))); }
  if (ev === 'stale') sd.files.set(CARDS, old);
  sd.files.set(`${AUDIO}book-new/001.m4a`, 'x');
  box = makeBox(sd, rule, nvs); box.boot();
  const order = Object.keys(before);
  for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(sim.uniform(0, i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  let wrong = 0; for (const c of order) if (box.place(c) !== before[c]) wrong++;
  return wrong;
}
const sim = new Sim({ seed: 7 }), B = 8;
console.log(`${B} books, 200 households per cell: scrambled decks / mean wrong cards`);
for (const ev of ['absent', 'torn', 'stale']) {
  let line = `  ${ev.padEnd(7)}`;
  for (const rule of ['as-written', 'present', 'parses', 'parses+gen']) {
    let hit = 0, w = 0; for (let k = 0; k < 200; k++) { const r = trial(rule, ev, sim, B); w += r; if (r) hit++; }
    line += `  ${rule}: ${String(hit).padStart(3)}/200 ${(w / 200).toFixed(1)}`;
  }
  console.log(line);
}
{ // a grown-up's deliberate clear must still win under parses+gen
  const sd = makeSD({ [`${AUDIO}a/1`]: 'x' }), nvs = {};
  let box = makeBox(sd, 'parses+gen', nvs); box.boot(); box.place('C0');
  const g = JSON.parse(sd.files.get(CARDS))._gen; sd.files.set(CARDS, JSON.stringify({ _gen: g }));
  box = makeBox(sd, 'parses+gen', nvs); box.boot();
  console.log(`  deliberate clear, edited file keeps _gen: ${JSON.stringify(box.cards)} restored: ${!!box.restored}`);
  sd.files.set(CARDS, '{}'); box = makeBox(sd, 'parses+gen', nvs); box.boot();
  console.log(`  deliberate clear written as bare {}:      ${JSON.stringify(box.cards)} restored: ${!!box.restored}`);
}

council/past/3/proposals/morphyx-absence:
// morphyx-absence.mjs — Morphyx, council 3 round 1.
//
// Question: in TAPE1 (SD-only, no radio), can the keeper property still break?
// Mozzie's boot rule (proposals/mozzie-cut.mjs, makeBox.boot): if neither cards.json nor cards.new
// parses, the box starts with no bindings. The cut model reaches that state only through power
// cuts, which the .new/rename dance closes. But the SD goes through a laptop every fortnight. If
// the file comes back missing (fresh or reformatted card, /tape dragged over from an old copy,
// file deleted or corrupted by a desktop OS), every card in the deck reads as fresh. Each one
// binds to the first free folder in the order the child happens to put them down.
//
// Two rules, same box logic otherwise (copied from mozzie-cut.mjs, which doesn't export it):
//   as-written : missing file  => bindings = {}
//   mirror     : the box also keeps bindings in its own flash (ESP32 NVS). A file that is
//                *present* governs (a grown-up who writes {} has cleared the deck on purpose).
//                A file that is *absent* restores from the mirror and logs it. Absence is not a decision.
//
//   node proposals/morphyx-absence.mjs
import { Sim } from '../tools/des/des.mjs';

const AUDIO = '/tape/audio/', CARDS = '/tape/cards.json';
function makeSD(files) {
  const sd = { files: new Map(Object.entries(files)) };
