// modulo-avatar.mjs: the avatar candidates as data, the SVGs written from that data, and the
// 48 px check run on the same data. One source, so the drawing tested is the drawing shipped.
//
//   node proposals/modulo-avatar.mjs            write the SVGs, print the 48 px measurements
//   node proposals/modulo-avatar.mjs --ascii    also print each candidate at 48 px as text
//   node proposals/modulo-avatar.mjs --png DIR  also write 48 px and 8x previews to DIR (not here: the lab keeps text)
//
// Shapes are only discs and thick polylines, so the rasterizer below is exact up to its
// 8x8 supersampling, and no image library is needed.
import { writeFileSync, mkdirSync } from 'node:fs';
import { deflateSync } from 'node:zlib';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const S = 512; // design units; the SVG viewBox is 0 0 512 512

const BG = '#14161c';
// Okabe–Ito: chosen to stay distinct under the three common colour-vision deficiencies.
const C = { vermillion: '#D55E00', sky: '#56B4E9', yellow: '#F0E442', white: '#F4F1EA' };

// Candidate A, "three": three equal discs on a triangle, one per part, with clear gaps.
function three() {
  const r = 78, R = 112, cx = 256, cy = 268; // R: centre of the figure to each disc centre
  const cols = [C.vermillion, C.sky, C.yellow];
  return [0, 1, 2].map((i) => {
    const a = -Math.PI / 2 + (i * 2 * Math.PI) / 3;
    return { kind: 'disc', x: cx + R * Math.cos(a), y: cy + R * Math.sin(a), r, fill: cols[i] };
  });
}

// Candidate B, "3:2": a Lissajous figure, the interval of a fifth drawn as one closed line.
function fifth() {
  const pts = [], n = 720, A = 150;
  for (let k = 0; k <= n; k++) {
    const t = (k / n) * 2 * Math.PI;
    pts.push([256 + A * Math.sin(3 * t + Math.PI / 2), 256 + A * Math.sin(2 * t)]);
  }
  return [{ kind: 'line', pts, w: 40, stroke: C.white }];
}

// Candidate C, "three on one line": candidate B's figure with three discs on it. Kept to show it fails.
function both() {
  const line = fifth()[0];
  const at = [0, 240, 480].map((k) => line.pts[k]);
  const cols = [C.vermillion, C.sky, C.yellow];
  return [{ ...line, w: 22 }, ...at.map(([x, y], i) => ({ kind: 'disc', x, y, r: 46, fill: cols[i] }))];
}

export const CANDIDATES = { 'modulo-avatar-three': three(), 'modulo-avatar-fifth': fifth(), 'modulo-avatar-both': both() };

const f = (v) => +v.toFixed(2);
export function svg(shapes) {
  const body = shapes.map((s) => s.kind === 'disc'
    ? `  <circle cx="${f(s.x)}" cy="${f(s.y)}" r="${s.r}" fill="${s.fill}"/>`
    : `  <polyline fill="none" stroke="${s.stroke}" stroke-width="${s.w}" stroke-linejoin="round" stroke-linecap="round" points="${s.pts.filter((_, i) => i % 4 === 0 || i === s.pts.length - 1).map(([x, y]) => `${f(x)},${f(y)}`).join(' ')}"/>`).join('\n');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${S} ${S}" width="${S}" height="${S}">\n  <rect width="${S}" height="${S}" fill="${BG}"/>\n${body}\n</svg>\n`;
}

// ---- rasterizer ---------------------------------------------------------------------------
const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
function segDist2(px, py, [ax, ay], [bx, by]) {
  const dx = bx - ax, dy = by - ay, L = dx * dx + dy * dy;
  const t = L ? Math.max(0, Math.min(1, ((px - ax) * dx + (py - ay) * dy) / L)) : 0;
  const qx = ax + t * dx - px, qy = ay + t * dy - py;
  return qx * qx + qy * qy;
}
function inside(s, x, y) {
  if (s.kind === 'disc') return (x - s.x) ** 2 + (y - s.y) ** 2 <= s.r * s.r;
  const h2 = (s.w / 2) ** 2;
  for (let i = 1; i < s.pts.length; i++) if (segDist2(x, y, s.pts[i - 1], s.pts[i]) <= h2) return true;
  return false;
}
const colorOf = (s) => hex(s.kind === 'disc' ? s.fill : s.stroke);

// Rasterize to N x N, with ss x ss samples a pixel. Returns rgb and, per pixel, which shape covers the
// majority of samples (-1 for background), for the measurements.
export function raster(shapes, N, ss = 8) {
  const rgb = new Float64Array(N * N * 3), owner = new Int16Array(N * N).fill(-1), bg = hex(BG);
  for (let py = 0; py < N; py++) for (let px = 0; px < N; px++) {
    const acc = [0, 0, 0], votes = new Map();
    for (let sy = 0; sy < ss; sy++) for (let sx = 0; sx < ss; sx++) {
      const x = ((px + (sx + 0.5) / ss) * S) / N, y = ((py + (sy + 0.5) / ss) * S) / N;
      let c = bg, who = -1;
      for (let k = shapes.length - 1; k >= 0; k--) if (inside(shapes[k], x, y)) { c = colorOf(shapes[k]); who = k; break; }
      for (let j = 0; j < 3; j++) acc[j] += c[j];
      votes.set(who, (votes.get(who) || 0) + 1);
    }
    for (let j = 0; j < 3; j++) rgb[(py * N + px) * 3 + j] = acc[j] / (ss * ss);
    owner[py * N + px] = [...votes].sort((a, b) => b[1] - a[1])[0][0];
  }
  return { rgb, owner, N };
}

// ---- measurements -------------------------------------------------------------------------
const lin = (c) => { c /= 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
const lum = ([r, g, b]) => 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
export const contrast = (a, b) => { const [x, y] = [lum(hex(a)), lum(hex(b))].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };

// Ink outside the circle the feed crops to, in design units (sampled on a 512 grid).
function inkOutsideCrop(shapes) {
  let out = 0, all = 0;
  for (let y = 0.5; y < S; y += 2) for (let x = 0.5; x < S; x += 2) {
    if (!shapes.some((s) => inside(s, x, y))) continue;
    all++;
    if ((x - 256) ** 2 + (y - 256) ** 2 > 256 * 256) out++;
  }
  return all ? out / all : 0;
}

// Thinnest part of each shape at N px: for discs the diameter; for lines the stroke width;
// and the narrowest background gap between two different shapes (measured on the design, scaled).
function features(shapes, N) {
  const k = N / S, out = { thinnest_px: Infinity, gap_px: Infinity };
  for (const s of shapes) out.thinnest_px = Math.min(out.thinnest_px, (s.kind === 'disc' ? 2 * s.r : s.w) * k);
  for (let i = 0; i < shapes.length; i++) for (let j = i + 1; j < shapes.length; j++) {
    const a = shapes[i], b = shapes[j];
    if (a.kind === 'disc' && b.kind === 'disc') out.gap_px = Math.min(out.gap_px, (Math.hypot(a.x - b.x, a.y - b.y) - a.r - b.r) * k);
    else out.gap_px = Math.min(out.gap_px, 0); // a disc on the line touches it by design
  }
  // a self-crossing line's tightest loop: smallest distance between non-neighbouring points, minus the width
  for (const s of shapes) if (s.kind === 'line') {
    let m = Infinity; const P = s.pts, n = P.length;
    for (let i = 0; i < n; i += 3) for (let j = i + 60; j < n - 1; j += 3) if (j - i < n - 60) {
      const d = Math.hypot(P[i][0] - P[j][0], P[i][1] - P[j][1]);
      if (d > s.w * 0.75) m = Math.min(m, d); // skip true crossings; we want near-misses
    }
    out.loop_hole_px = Math.max(0, (m - s.w) * k);
  }
  return out;
}

// Pixels at 48 that are majority-owned by each shape, inside the crop: does each part survive?
function partsAt(r, shapes) {
  const { owner, N } = r, n = new Array(shapes.length).fill(0);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    if ((x + 0.5 - N / 2) ** 2 + (y + 0.5 - N / 2) ** 2 > (N / 2) ** 2) continue;
    const o = owner[y * N + x]; if (o >= 0) n[o]++;
  }
  return n;
}

export function measure(shapes, N = 48) {
  const r = raster(shapes, N);
  const fills = [...new Set(shapes.map((s) => s.fill || s.stroke))];
  const pairs = [];
  for (let i = 0; i < fills.length; i++) for (let j = i + 1; j < fills.length; j++) pairs.push(+contrast(fills[i], fills[j]).toFixed(2));
  return {
    px: N,
    contrast_vs_bg: Object.fromEntries(fills.map((c) => [c, +contrast(c, BG).toFixed(2)])),
    contrast_between_fills: pairs,
    ink_outside_round_crop: +inkOutsideCrop(shapes).toFixed(4),
    // gap_px is null when there is only one shape (no gap to measure)
    ...Object.fromEntries(Object.entries(features(shapes, N)).map(([k, v]) => [k, Number.isFinite(v) ? +v.toFixed(2) : null])),
    pixels_per_part_in_crop: partsAt(r, shapes),
  };
}

function ascii(r) {
  const { rgb, N } = r, ramp = ' .:-=+*#%@';
  const rows = [];
  for (let y = 0; y < N; y++) {
    let line = '';
    for (let x = 0; x < N; x++) {
      if ((x + 0.5 - N / 2) ** 2 + (y + 0.5 - N / 2) ** 2 > (N / 2) ** 2) { line += '  '; continue; }
      const i = (y * N + x) * 3, L = lum([rgb[i], rgb[i + 1], rgb[i + 2]]) ** (1 / 2.2);
      const ch = ramp[Math.min(9, Math.floor(L * 10))]; line += ch + ch;
    }
    rows.push(line);
  }
  return rows.join('\n');
}

// Minimal PNG writer (RGB, 8-bit), for previews outside the lab only.
function png(r, scale = 1, crop = true) {
  const { rgb, N } = r, W = N * scale, crcT = [];
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; crcT[n] = c >>> 0; }
  const crc = (b) => { let c = 0xffffffff; for (const x of b) c = crcT[(c ^ x) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
  const chunk = (t, d) => { const l = Buffer.alloc(4); l.writeUInt32BE(d.length); const td = Buffer.concat([Buffer.from(t), d]); const c = Buffer.alloc(4); c.writeUInt32BE(crc(td)); return Buffer.concat([l, td, c]); };
  const raw = Buffer.alloc(W * (W * 3 + 1));
  for (let y = 0; y < W; y++) {
    raw[y * (W * 3 + 1)] = 0;
    for (let x = 0; x < W; x++) {
      const sx = Math.floor(x / scale), sy = Math.floor(y / scale), i = (sy * N + sx) * 3;
      const out = crop && (sx + 0.5 - N / 2) ** 2 + (sy + 0.5 - N / 2) ** 2 > (N / 2) ** 2;
      for (let j = 0; j < 3; j++) raw[y * (W * 3 + 1) + 1 + x * 3 + j] = out ? 255 : Math.round(rgb[i + j]);
    }
  }
  const ih = Buffer.alloc(13); ih.writeUInt32BE(W, 0); ih.writeUInt32BE(W, 4); ih[8] = 8; ih[9] = 2;
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ih), chunk('IDAT', deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const pngDir = process.argv.includes('--png') ? process.argv[process.argv.indexOf('--png') + 1] : null;
  for (const [name, shapes] of Object.entries(CANDIDATES)) {
    const text = svg(shapes);
    writeFileSync(join(HERE, `${name}.svg`), text);
    console.log(name, `(${Buffer.byteLength(text)} bytes of SVG)`, JSON.stringify(measure(shapes, 48)));
    if (process.argv.includes('--ascii')) console.log(ascii(raster(shapes, 48)));
    if (pngDir) {
      mkdirSync(pngDir, { recursive: true });
      const r = raster(shapes, 48);
      writeFileSync(join(pngDir, `${name}-48.png`), png(r, 1));
      writeFileSync(join(pngDir, `${name}-48x8.png`), png(r, 8));
      writeFileSync(join(pngDir, `${name}-400.png`), png(raster(shapes, 400, 2), 1));
    }
  }
}

// Morphyx's avatar candidates: drawn and measured from the same polygon data.
// node proposals/morphyx-avatar.mjs            -> writes SVGs, prints 48 px measurements
// node proposals/morphyx-avatar.mjs --ascii    -> also prints each 48 px raster as text
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = dirname(fileURLToPath(import.meta.url));
const S = 512, C = 256, BG = '#14161c';           // same ground as Modulo's, so the two sets compare
const FILLS = ['#D55E00', '#56B4E9', '#F0E442'];  // Okabe-Ito: vermillion, sky, yellow
const TAU = Math.PI * 2;

// --- shapes: {poly, fill} filled polygons, {line:[a,b], w, fill} thick segments, painted in order
function reuleaux(side = 372, gap = 30) {
  // Reuleaux triangle: each edge is an arc centred on the opposite corner, radius = side.
  // Split into three sectors (one per part) by bars of background from the centre to each corner.
  const R = side / Math.sqrt(3);                    // centre to corner
  const cy = C + (R - (side - R)) / 2;              // centre the figure's height in the square
  const V = [0, 1, 2].map((k) => { const a = -Math.PI / 2 + k * TAU / 3; return [C + R * Math.cos(a), cy + R * Math.sin(a)]; });
  const shapes = [];
  for (let k = 0; k < 3; k++) {
    // sector k spans corner V[k] -> V[k+1]; its outer edge is the arc centred on the third corner
    const a = V[k], b = V[(k + 1) % 3], o = V[(k + 2) % 3];
    const t0 = Math.atan2(a[1] - o[1], a[0] - o[0]); let t1 = Math.atan2(b[1] - o[1], b[0] - o[0]);
    if (t1 < t0) t1 += TAU;
    const poly = [[C, cy]];
    for (let i = 0; i <= 48; i++) { const t = t0 + (t1 - t0) * i / 48; poly.push([o[0] + side * Math.cos(t), o[1] + side * Math.sin(t)]); }
    shapes.push({ poly, fill: FILLS[k] });
  }
  for (const v of V) shapes.push({ line: [[C, cy], v], w: gap, fill: BG, cap: 'butt' });
  return { shapes, feature: { gap_px: gap, sector_part: 'one sector per part' } };
}

function gear(cx, cy, root, tip, n, phase) {
  const poly = [];
  for (let i = 0; i < n; i++) {
    const a = phase + i * TAU / n, h = TAU / n;
    const pts = [[a, root], [a + h * 0.1, tip], [a + h * 0.4, tip], [a + h * 0.5, root]];
    for (const [t, r] of pts) poly.push([cx + r * Math.cos(t), cy + r * Math.sin(t)]);
  }
  return poly;
}
function gears() {
  // three meshing spur gears, 9 teeth each, centres on a triangle
  const root = 66, tip = 88, n = 9, d = 2 * root + 14, R = d / Math.sqrt(3);
  const shapes = [0, 1, 2].map((k) => {
    const a = -Math.PI / 2 + k * TAU / 3;
    return { poly: gear(C + R * Math.cos(a), C + 12 + R * Math.sin(a), root, tip, n, a + k * Math.PI / n), fill: FILLS[k] };
  });
  return { shapes, feature: { tooth_tip_px_at_512: +(0.3 * TAU / n * tip).toFixed(1) } };
}

const CANDIDATES = { reuleaux: reuleaux(), gears: gears() };

// --- svg
function svg(shapes) {
  const f = (n) => +n.toFixed(2);
  const body = shapes.map((s) => s.poly
    ? `  <polygon fill="${s.fill}" points="${s.poly.map(([x, y]) => `${f(x)},${f(y)}`).join(' ')}"/>`
    : `  <line x1="${f(s.line[0][0])}" y1="${f(s.line[0][1])}" x2="${f(s.line[1][0])}" y2="${f(s.line[1][1])}" stroke="${s.fill}" stroke-width="${s.w}" stroke-linecap="butt"/>`);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${S} ${S}" width="${S}" height="${S}">\n  <rect width="${S}" height="${S}" fill="${BG}"/>\n${body.join('\n')}\n</svg>\n`;
}

// --- raster (same data)
function inPoly(poly, x, y) {
  let c = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i], [xj, yj] = poly[j];
    if ((yi > y) !== (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c;
  }
  return c;
}
function onLine(s, x, y) {
  const [[ax, ay], [bx, by]] = s.line, dx = bx - ax, dy = by - ay, L2 = dx * dx + dy * dy;
  const t = ((x - ax) * dx + (y - ay) * dy) / L2;
  if (t < 0 || t > 1) return false;                // butt caps
  const px = ax + t * dx - x, py = ay + t * dy - y;
  return px * px + py * py <= (s.w / 2) ** 2;
}
const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const lum = ([r, g, b]) => { const l = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; }; return 0.2126 * l(r) + 0.7152 * l(g) + 0.0722 * l(b); };
const contrast = (a, b) => { const [x, y] = [lum(hex(a)), lum(hex(b))].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };

function raster(shapes, N, ss = 8) {
  const owner = new Int16Array(N * N).fill(-1), cover = new Float64Array(N * N);
  let outside = 0;
  for (let py = 0; py < N; py++) for (let px = 0; px < N; px++) {
    const votes = new Map();
    for (let sy = 0; sy < ss; sy++) for (let sx = 0; sx < ss; sx++) {
      const x = (px + (sx + 0.5) / ss) * S / N, y = (py + (sy + 0.5) / ss) * S / N;
      let who = -1;
      shapes.forEach((s, i) => { if (s.poly ? inPoly(s.poly, x, y) : onLine(s, x, y)) who = s.fill === BG ? -1 : FILLS.indexOf(s.fill); });
      if (who >= 0) { votes.set(who, (votes.get(who) || 0) + 1); if ((x - C) ** 2 + (y - C) ** 2 > C * C) outside++; }
    }
    let best = -1, n = 0, tot = 0;
    for (const [k, v] of votes) { tot += v; if (v > n) { n = v; best = k; } }
    cover[py * N + px] = tot / (ss * ss);
    if (tot / (ss * ss) >= 0.5) owner[py * N + px] = best;
  }
  return { owner, outside, N };
}

function measure(name, N = 48) {
  const { shapes, feature } = CANDIDATES[name], r = raster(shapes, N);
  const counts = FILLS.map((_, k) => r.owner.filter((o) => o === k).length);
  // thinnest visible separation: for each pair of parts, smallest pixel distance between their pixels
  let minSep = Infinity;
  const pts = FILLS.map((_, k) => { const a = []; r.owner.forEach((o, i) => { if (o === k) a.push([i % N, Math.floor(i / N)]); }); return a; });
  for (let i = 0; i < 3; i++) for (let j = i + 1; j < 3; j++) for (const [x1, y1] of pts[i]) for (const [x2, y2] of pts[j]) minSep = Math.min(minSep, Math.hypot(x1 - x2, y1 - y2));
  const scale = N / S;
  const feat = Object.fromEntries(Object.entries(feature).map(([k, v]) => typeof v === 'number' ? [k.replace('_at_512', '') + '_at_48', +(v * scale).toFixed(2)] : [k, v]));
  return {
    candidate: name, N,
    ink_outside_round_crop_supersamples: r.outside,
    pixels_per_part: counts,
    nearest_pixels_of_different_parts: +minSep.toFixed(2),
    ...feat,
    contrast_vs_bg: Object.fromEntries(FILLS.map((c) => [c, +contrast(c, BG).toFixed(2)])),
  };
}

function ascii(name, N = 48) {
  const r = raster(CANDIDATES[name].shapes, N), ch = ['R', 'b', 'y'];
  const rows = [];
  for (let y = 0; y < N; y++) { let s = ''; for (let x = 0; x < N; x++) { const inCrop = (x + 0.5 - N / 2) ** 2 + (y + 0.5 - N / 2) ** 2 <= (N / 2) ** 2; const o = r.owner[y * N + x]; s += o >= 0 ? ch[o] : inCrop ? '.' : ' '; } rows.push(s); }
  return rows.join('\n');
}

for (const name of Object.keys(CANDIDATES)) {
  writeFileSync(join(HERE, `morphyx-avatar-${name}.svg`), svg(CANDIDATES[name].shapes));
  console.log(JSON.stringify(measure(name)));
  if (process.argv.includes('--ascii')) console.log(ascii(name) + '\n');
}

council/past/7/proposals/modulo-road.mjs:
// Modulo's rules of the road, applied mechanically to the 115 labelled cases in past/6.
// Rules were written before this script was first run; the run is the measurement.
// Usage: node proposals/modulo-road.mjs [--list]
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const past = join(here, '..', 'past', '6', 'proposals');
const load = (n) => JSON.parse(readFileSync(join(past, `${n}-triage-cases.json`), 'utf8'));

const US = /^(@?(us|miniphim|modulo|morphyx|mozzie)(\.delve\.town)?)$/i;
const AT_US = /@(miniphim|modulo|morphyx|mozzie)\b/i;
const PERSON = /^@?modalmobius/i;

// Facts the caller can compute before the call. Each comes from the record, not from judgement.
// Where a case file supplies the fact, use it; otherwise derive it from the record the same way the door would.
function facts(c) {
  const f = { ...(c.facts || {}), ...((c.mention && c.mention.facts) || {}) };
  const m = c.mention || {};
  const author = String(m.by || m.author || '');
  const text = String(m.text || '');
  const thread = c.thread || [];
  const who = (p) => String(p.by || p.who || '');
  const ours = f.ours ?? f.tagged_because_root_is_ours ?? thread.some((p) => US.test(who(p)));
  const iOurs = thread.findIndex((p) => US.test(who(p)));
  // talked before: the author posted in a thread we also posted in (public record, no note kept)
  const talked = iOurs >= 0 && thread.some((p) => who(p).replace(/^@/, '') === author.replace(/^@/, ''));
  return {
    person: PERSON.test(author),
    bot: Boolean(f.author_bot ?? f.is_bot_label ?? false),
    addressed: Boolean(f.addressed_to_us || f.quote_of_our_post || m.kind === 'quote' && ours || AT_US.test(text) || (f.addressed_to_us == null && ours)),
    link: /https?:\/\/|\(link\)/i.test(text),
    ours: Boolean(ours),
    talked,
    asks: Boolean(f.has_question ?? f.question ?? text.includes('?')),
    data: Boolean(f.has_data ?? f.has_attachment ?? /https?:\/\/|\battached\b|\.csv\b/i.test(text)),
    hours: f.hours_old ?? (f.thread_age_days != null ? f.thread_age_days * 24 : 0),
    capped: (f.author_replies_today ?? 0) >= 2,
    words: text.replace(/@\S+/g, '').split(/\s+/).filter((w) => /[a-z0-9]/i.test(w)).length,
  };
}

// The rules. First match wins. Output: none (nothing) | quick (a few words) | day (the real thing).
export function road(x) {
  if (x.person) return ['R0', 'day'];
  if (x.bot || !x.addressed) return ['R1', 'none'];
  if (x.capped) return ['R2', 'none'];
  if (x.ours) return ['R3', x.data ? 'day' : 'quick'];
  if (x.hours > 72) return ['R4', 'none'];
  if (!x.asks) return ['R5', 'none'];
  if (x.data) return ['R6', 'day'];
  return ['R7', x.talked ? 'day' : 'quick'];
}

// v2: one revision after reading v1's misses, so its score on these cases is optimistic.
// Changes: age before thread; our thread owes nothing to a mention that asks nothing and carries nothing;
// data without a question gets a few words, not silence; the real thing is never assigned by facts
// alone except for data + question (everything else that might deserve it is "a few words, then read").
export function road2(x) {
  if (x.person) return ['R0', 'day'];
  if (x.bot || !x.addressed) return ['R1', 'none'];
  if (x.capped) return ['R2', 'none'];
  if (x.hours > 72) return ['R3', 'none'];
  if (!x.asks && !x.data) return ['R4', 'none'];
  if (x.asks && x.data) return ['R5', 'day'];
  return ['R6', 'quick'];
}

// v3: v2 plus one fact, word count. In our own thread, a mention of 8+ words gets a few words even
// without a question (corrections rarely end in '?'); under 8 words with no question gets nothing.
export function road3(x) {
  if (x.person) return ['R0', 'day'];
  if (x.bot || !x.addressed) return ['R1', 'none'];
  if (x.capped) return ['R2', 'none'];
  if (x.hours > 72) return ['R3', 'none'];
  if (x.asks && x.data) return ['R4', 'day'];
  if (x.asks || x.data || (x.ours && x.words >= 8)) return ['R5', 'quick'];
  return ['R6', 'none'];
}

// final (proposed): the facts set a floor only. 'quick' here means "read it, at least a few words";
// the real thing is raised by the reader after reading, never assigned from the envelope, except for the person.
// Talked-before (we replied to them in public before) lowers the bar the same way a question does.
export function roadF(x) {
  if (x.person) return ['R0', 'day'];
  if (x.bot || !x.addressed || x.hours > 72) return ['R1', 'none'];
  if (x.capped) return ['R2', 'none'];
  if (x.asks || x.data || x.link || x.talked || (x.ours && x.words >= 8)) return ['R3', 'quick'];
  return ['R4', 'none'];
}

const files = ['modulo', 'morphyx', 'mozzie'];
const rows = [];
const F = process.argv.includes('--final');
const v2 = process.argv.includes('--v2'), v3 = process.argv.includes('--v3');
for (const n of files) for (const c of load(n).cases) {
  const x = facts(c);
  const [rule, out] = (F ? roadF : v3 ? road3 : v2 ? road2 : road)(x);
  rows.push({ id: c.id, author: n, label: c.label, rule, out, x, text: (c.mention?.text || '').slice(0, 110) });
}

const scored = rows.filter((r) => r.label !== 'bail');
const agree = scored.filter((r) => r.out === r.label).length;
const n = scored.length;
const p = agree / n, z = 1.96;
const lo = (p + z*z/(2*n) - z*Math.sqrt(p*(1-p)/n + z*z/(4*n*n))) / (1 + z*z/n);
const hi = (p + z*z/(2*n) + z*Math.sqrt(p*(1-p)/n + z*z/(4*n*n))) / (1 + z*z/n);
console.log(`cases ${rows.length}, bail ${rows.length - n}, scored ${n}`);
console.log(`rule = label: ${agree}/${n} (${(100*p).toFixed(1)}%, Wilson 95% ${(100*lo).toFixed(1)}–${(100*hi).toFixed(1)}%)`);
const L = ['day', 'quick', 'none'];
console.log('confusion (rows = label, cols = rule):');
for (const a of L) console.log(`  ${a.padEnd(6)} ` + L.map((b) => String(scored.filter((r) => r.label === a && r.out === b).length).padStart(4)).join(''));
for (const f of files) { const s = scored.filter((r) => r.author === f); console.log(`  ${f}: ${s.filter((r) => r.out === r.label).length}/${s.length}`); }
const byRule = {};
for (const r of scored) { byRule[r.rule] ??= [0, 0]; byRule[r.rule][0]++; if (r.out === r.label) byRule[r.rule][1]++; }
console.log('by rule (fired, agreed):', JSON.stringify(byRule));
{ const fl = scored.filter((r) => (r.out === 'none') === (r.label === 'none')).length;
  console.log(`floor axis (none vs not-none): ${fl}/${n}; label not-none but rule none: ${scored.filter((r) => r.out === 'none' && r.label !== 'none').map((r) => r.id).join(' ')}`);
  console.log(`label none but rule reads it: ${scored.filter((r) => r.out !== 'none' && r.label === 'none').map((r) => r.id).join(' ')}`); }
console.log(`day labelled, rule says none:${scored.filter((r) => r.label === 'day' && r.out === 'none').length}`);
if (process.argv.includes('--list')) for (const r of rows.filter((r) => r.out !== r.label))
