// harness — one model, two runs: record it under runRealtime with a fake clock, replay
// its log under run(), and check every decision matches. No dependencies beyond des.
// Decisions SPEC.md leaves open are marked DECISION and listed in README.md.
import { Sim } from './tools/des/des.mjs';

// A clock that only moves when slept. sleep(ms) delivers at most one due injection:
// it advances the clock to that injection's time, injects, and returns, so the run
// loop sees the injected entry before anything later happens.
function fakeClock(sim, pending, scale, log) {
  const clock = {
    t: 0,
    now() { return clock.t; },
    sleep(ms) {
      const end = clock.t + ms;
      // DECISION: an injection is due when its clock time is strictly before the end of
      // the sleep. One at exactly the next event's time waits for the next sleep, so it
      // is delivered after every entry at that sim time, the same rule replay uses.
      if (pending.length && pending[0].at * scale < end) {
        const inj = pending.shift();
        clock.t = Math.max(clock.t, inj.at * scale);
        deliver(sim, inj.name, inj.value, log, inj.at);
      } else clock.t = end;
      return Promise.resolve();
    },
  };
  return clock;
}

// Inject and log the injection at the sim time it is actually delivered (from inside
// the scheduled entry), so the log's order is the order the model saw.
// DECISION (Morphyx, turn 2): the entry is scheduled at sim time `at` exactly, not at
// clock ÷ scale, which drifts an ulp (3 × 0.37 ÷ 0.37 = 2.9999999999999996). Same wake as
// des's _external; never earlier than now.
function deliver(sim, name, value, log, at) {
  const ext = sim._external;
  sim._external = function (fn) {
    sim._external = ext;
    sim.schedule(Math.max(0, at - sim.now), () => { log.push({ t: sim.now, kind: 'inject', data: { name, value: copy(value) } }); fn(); });
    if (sim._wake) { const w = sim._wake; sim._wake = null; w(); }
  };
  try { sim.inject(name, value); } finally { sim._external = ext; }
}

// DECISION: decision data is copied when written, so a model that later mutates the object
// it logged can't rewrite history. fi-5f90c6 fixed (Morphyx, tape turn 1): the copy goes
// through encode/decode, which keep NaN, ±Infinity, -0 and absence. JSON turned NaN and
// ±Infinity into null, so a NaN reading and a missing one looked the same.
function copy(x) { return x === undefined ? null : decode(encode(x)); }

// Every value is written as a tagged array, so nothing a caller writes can be read as the
// encoding: a caller's string is always inside ['s', ...], a caller's object inside ['o', ...].
//   ['z'] null   ['s', str]   ['b', bool]   ['n', finite number]
//   ['x', 'NaN' | 'Infinity' | '-Infinity' | '-0']
//   ['a', [...]] array; an undefined element or a hole is ['u']
//   ['o', [[key, value], ...]] object; a key whose value is undefined is left out (absent)
//   ['u'] undefined at the top level or in an array slot
function tag(v) {
  if (v === null) return ['z'];
  if (v === undefined) return ['u'];
  switch (typeof v) {
    case 'string': return ['s', v];
    case 'boolean': return ['b', v];
    case 'number':
      if (Number.isNaN(v)) return ['x', 'NaN'];
      if (v === Infinity) return ['x', 'Infinity'];
      if (v === -Infinity) return ['x', '-Infinity'];
      if (Object.is(v, -0)) return ['x', '-0'];
      return ['n', v];
    case 'object':
      if (Array.isArray(v)) return ['a', Array.from(v, tag)];
      if (typeof v.toJSON === 'function') return tag(v.toJSON());
      return ['o', Object.keys(v).filter((k) => v[k] !== undefined).map((k) => [k, tag(v[k])])];
    default: throw new TypeError(`encode: cannot encode a ${typeof v}`);
  }
}
const SPECIAL = { NaN: NaN, Infinity: Infinity, '-Infinity': -Infinity, '-0': -0 };
function put(o, k, v) { Object.defineProperty(o, k, { value: v, enumerable: true, writable: true, configurable: true }); }
function untag(t) {
  if (!Array.isArray(t)) throw new TypeError('decode: not an encoded value');
  const [k, p] = t;
  switch (k) {
    case 'z': return null;
    case 'u': return undefined;
    case 's': case 'b': case 'n': return p;
    case 'x': if (Object.hasOwn(SPECIAL, p)) return SPECIAL[p]; break;
    case 'a': return p.map(untag);
    case 'o': { const o = {}; for (const [key, val] of p) { const x = untag(val); if (x !== undefined) put(o, key, x); } return o; }
  }
  throw new TypeError(`decode: unknown tag ${JSON.stringify(k)}`);
}
export function encode(value) { return JSON.stringify(tag(value)); }
export function decode(text) { return untag(JSON.parse(text)); }

function attach(sim, log) {
  sim.decide = (kind, data) => {
    if (typeof kind !== 'string' || !kind) throw new TypeError('decide needs a kind (string)');
    log.push({ t: sim.now, kind, data: copy(data) });
  };
}

export async function record(model, { seed, until, scale = 1, injections = [] } = {}) {
  if (typeof model !== 'function') throw new TypeError('record needs a model function');
  if (!(scale > 0)) throw new RangeError('scale must be > 0');
  for (const j of injections) if (!(j && j.at >= 0 && typeof j.name === 'string')) throw new RangeError(`bad injection ${JSON.stringify(j)}`);
  const log = [];
  // Stable sort: injections at the same time keep the order given.
  const pending = injections.map((j, i) => ({ ...j, i })).sort((a, b) => a.at - b.at || a.i - b.i);
  const sim = new Sim({ seed, clock: null });
  sim._clock = fakeClock(sim, pending, scale, log);
  attach(sim, log);
  await model(sim);
  await sim.runRealtime({ until, scale });
  return log;
}

export async function replay(model, log, { seed, until } = {}) {
  if (typeof model !== 'function') throw new TypeError('replay needs a model function');
  if (!Array.isArray(log)) throw new TypeError('replay needs a log array');
  const got = [];
  const sim = new Sim({ seed });
  attach(sim, got);
  await model(sim);
  for (const e of log) {
    if (e.kind !== 'inject') continue;
    // Recorded rule: an injection at t is delivered after every entry at times <= t
    // that existed when the clock passed t. run({until: t}) processes exactly those
    // (plus same-time entries they spawn, which in record also ran before the sleep).
    sim.run({ until: Math.max(e.t, sim.now) });
    // run() leaves now at until, so the injection lands at e.t, as in record.
    sim.inject(e.data.name, e.data.value);
  }
  if (until !== undefined) { if (until >= sim.now) sim.run({ until }); }
  else sim.run();
  const want = log.filter((e) => e.kind !== 'inject');
  const mismatches = [];
  const n = Math.max(want.length, got.length);
  for (let i = 0; i < n; i++) {
    const a = want[i], b = got[i];
    if (!same(a, b)) mismatches.push({ index: i, expected: a ?? null, got: b ?? null });
  }
  return { ok: mismatches.length === 0, mismatches };
}

// Canonical form: keys sorted, then the tagged encoding, so NaN, null and absent all differ.
function sortKeys(x) {
  if (Array.isArray(x)) return x.map(sortKeys);
  if (x && typeof x === 'object') { const o = {}; for (const k of Object.keys(x).sort()) if (x[k] !== undefined) put(o, k, sortKeys(x[k])); return o; }
  return x;
}
function canon(x) { return encode(sortKeys(x)); }
function same(a, b) {
  if (!a || !b) return false;
  return Object.is(a.t, b.t) && a.kind === b.kind && canon(a.data) === canon(b.data);
}

projects/p-tape1/tape-lib/tag.js:
// tape/lib/tag.js — the card data model.
//
// THE ONE FACT THIS FILE EXISTS TO ENFORCE: an NFC tag cannot hold audio.
// The biggest tag anyone sells cheaply (NTAG216) has 888 bytes of user memory.
// One minute of speech at 24 kbps Opus is 180,000 bytes. A tag is off by three
// to four orders of magnitude. So the tag holds a *pointer* — a 64-bit card id
// — and the audio lives on the box's SD card, addressed through the manifest
// (see catalog.js). Everything good about this design falls out of that:
//
//   • a card costs ~20¢ instead of $19.99
//   • re-pointing a card at new audio never touches the card
//   • many books per card is free — the manifest maps one card to a playlist
//   • a card written by one box works on another that has the same audio
//
// We write TWO NDEF records to every card:
//   1. a URL record  → tap the card on any phone and it opens the card's page
//   2. an external record "minomobi.com:tape" → the compact body the box reads
//
// Both together fit inside NTAG213's 144 bytes, so the cheapest sticker works.
// tag.selftest.mjs asserts that, and will fail if this file ever grows past it.

export const CARD_MAGIC = 0x5450;          // 'TP'
export const CARD_VERSION = 1;
export const CARD_EXTERNAL_TYPE = 'minomobi.com:tape';
export const CARD_URL_BASE = 'https://tape.mino.mobi/c/';

export const FLAG_SHUFFLE = 0x01;  // play the card's playlist in random order
export const FLAG_RESUME  = 0x02;  // remember the position when the card leaves
export const FLAG_LOCKED  = 0x04;  // the studio refuses to rewrite this card

export const CARD_ID_BYTES = 8;
export const CARD_ID_CHARS = 13;   // ceil(64 / 5) Crockford base32 characters
export const LABEL_MAX_BYTES = 32;
export const CARD_BODY_MAX = 13 + LABEL_MAX_BYTES;  // 45

// User memory, in bytes, of the tags worth considering. Sourced from the NXP
// datasheets; see design/ for why 125 kHz RFID is not on this list.
export const TAG_CAPACITY = {
  'MIFARE Ultralight': 48,
  NTAG213: 144,
  NTAG215: 504,
  NTAG216: 888,
  'MIFARE Classic 1K': 752,
  'MIFARE DESFire EV3 8K': 8192,
};

// The cheapest tag we promise to work on. Everything here is sized to fit it.
export const TARGET_TAG = 'NTAG213';

const B32 = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';  // Crockford: no I, L, O, U

export function base32Encode(bytes) {
  let out = '', acc = 0, bits = 0;
  for (const b of bytes) {
    acc = (acc << 8) | b;
    bits += 8;
    while (bits >= 5) { bits -= 5; out += B32[(acc >> bits) & 31]; }
  }
  if (bits) out += B32[(acc << (5 - bits)) & 31];
  return out;
}

export function base32Decode(str) {
  // Crockford's forgiving reads: a human copying an id off a card by eye may
  // write O for 0 and I or L for 1. Hyphens are decoration.
  const norm = String(str).toUpperCase().replace(/-/g, '')
    .replace(/O/g, '0').replace(/[IL]/g, '1');
  let acc = 0, bits = 0;
  const out = [];
  for (const ch of norm) {
    const v = B32.indexOf(ch);
    if (v < 0) throw new Error(`not a card id: bad character ${JSON.stringify(ch)}`);
    acc = (acc << 5) | v;
    bits += 5;
    if (bits >= 8) { bits -= 8; out.push((acc >> bits) & 0xff); }
  }
  return Uint8Array.from(out);
}

/** A fresh random card id, as its 13-character human/URL form. */
export function newCardId(random = defaultRandom) {
  return base32Encode(random(CARD_ID_BYTES));
}

function defaultRandom(n) {
  const b = new Uint8Array(n);
  // Browsers and node >=19 both expose this on globalThis.
  globalThis.crypto.getRandomValues(b);
  return b;
}

export function isCardId(s) {
  if (typeof s !== 'string') return false;
  const norm = s.toUpperCase().replace(/-/g, '');
  if (norm.length !== CARD_ID_CHARS) return false;
  try { return base32Decode(norm).length === CARD_ID_BYTES; } catch { return false; }
}

export function cardUrl(id) { return CARD_URL_BASE + id; }

/** Pack the body the box reads off the tag. */
export function encodeCard({ id, label = '', flags = FLAG_RESUME }) {
  if (!isCardId(id)) throw new Error(`encodeCard: ${JSON.stringify(id)} is not a card id`);
  const labelBytes = new TextEncoder().encode(label);
  if (labelBytes.length > LABEL_MAX_BYTES) {
    throw new Error(`encodeCard: label is ${labelBytes.length} bytes, max ${LABEL_MAX_BYTES}`);
  }
  const idBytes = base32Decode(id);
  const out = new Uint8Array(13 + labelBytes.length);
  out[0] = (CARD_MAGIC >> 8) & 0xff;
  out[1] = CARD_MAGIC & 0xff;
  out[2] = CARD_VERSION;
  out[3] = flags & 0xff;
  out.set(idBytes, 4);
  out[12] = labelBytes.length;
  out.set(labelBytes, 13);
  return out;
}

export function decodeCard(bytes) {
  const b = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  if (b.length < 13) throw new Error('decodeCard: too short to be a tape card');
  if (((b[0] << 8) | b[1]) !== CARD_MAGIC) throw new Error('decodeCard: not a tape card');
  if (b[2] !== CARD_VERSION) throw new Error(`decodeCard: card version ${b[2]}, this build reads ${CARD_VERSION}`);
  const labelLen = b[12];
  if (b.length < 13 + labelLen) throw new Error('decodeCard: label runs past the end of the record');
  return {
    version: b[2],
    flags: b[3],
    id: base32Encode(b.subarray(4, 12)),
    label: new TextDecoder().decode(b.subarray(13, 13 + labelLen)),
  };
}

/**
 * The records to hand to Web NFC's NDEFReader.write({ records }).
 * Shape matches NDEFRecordInit so this is passed straight through.
 */
export function ndefRecords(card) {
  return [
    { recordType: 'url', data: cardUrl(card.id) },
    { recordType: CARD_EXTERNAL_TYPE, data: encodeCard(card) },
  ];
}

/**
 * Bytes this message actually occupies on a Type 2 tag, TLV wrapper included.
 * Used to prove at test time that a maximal card still fits an NTAG213.
 */
export function ndefByteLength(records) {
  let msg = 0;
  for (const r of records) {
    if (r.recordType === 'url') {
      // TNF well-known, type 'U'. Payload = 1 abbreviation byte + the rest of
      // the URI; 'https://' is abbreviation 0x04.
      const rest = String(r.data).replace(/^https:\/\//, '');
      msg += 4 + 1 + new TextEncoder().encode(rest).length;
    } else {
      // TNF external. Header = flags + typeLen + payloadLen + the type string.
      const type = new TextEncoder().encode(r.recordType).length;
      const payload = r.data.length;
      msg += 3 + type + payload;
    }
  }
  // NDEF message TLV: tag 0x03, length (1 byte under 255), value, terminator.
  return 1 + (msg < 255 ? 1 : 3) + msg + 1;
}

export function fitsTag(records, tag = TARGET_TAG) {
  const cap = TAG_CAPACITY[tag];
  if (!cap) throw new Error(`fitsTag: unknown tag ${tag}`);
  return ndefByteLength(records) <= cap;
}

