  await b2.poll(0.15, { crowd: true }); await b2.poll(0.2, tagRead('04BB', ID[1]));
  assert(b2.events.at(-1).type === 'play' && b2.events.at(-1).title === 'a', 'the next new card binds a free title');
});

// ---------- P: playing ----------
await check('T-P-PLAY', async () => {
