    const whole = lines.filter((l) => l.length >= 2 && known.has(l[1]) && Number.isFinite(+l[0]));
    assert(lines.length - whole.length <= 1, `at most the torn line is unreadable: ${JSON.stringify(lines)}`);
    const boots = whole.filter((l) => l[1] === 'boot');
