  assert.equal(tpm({ id: 'r', direction: 'max', threshold: 0.13655512552659518, history: [{ at: '2026-01-01', value: 0.010309278350515464 }, { at: '2026-01-02', value: 0.07343220193855533 }] }, {}).projectedBreach, '2026-01-03');
});

