        const K = SY * D - N * Sx, M = n * N, E = n * D;
        // max: K + Mx > TS·E with M > 0; min: K + Mx < TS·E with M < 0. Both: x > (TS·E − K) ÷ M.
        let x = fdiv(TS * E - K, M) + 1n;
