    const n = BigInt(h.length); let sx = Z, sy = Z, sxx = Z, sxy = Z;
    for (const p of h) { const x = Q.of(day(p.at) - d0), y = Q.of(p.value); sx = sx.add(x); sy = sy.add(y); sxx = sxx.add(x.mul(x)); sxy = sxy.add(x.mul(y)); }
