}

export function earned(reqs, links, evidence, plan, actuals, { asOf } = {}) {
  const wps = plan.workPackages, base = Math.min(...wps.map(w => day(w.start)));
  const dn = s => day(s) - base + 1, sm = status(reqs, links, evidence, { asOf });
